"""
数論変換 (NTT / Number Theoretic Transform) & 畳み込み (mod 998244353)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
素数 mod = 998244353 (原始根 g = 3) 上での高速離散フーリエ変換。
浮動小数点誤差なく、多項式の積 A(x) * B(x) を O(N log N) で計算。

【引数・戻り値】
- ntt(a, inv=False): 長さ 2^k の配列 a をインプレース変換
- convolve_ntt(a, b): 数列 a, b の畳み込み積を返す
"""

MOD = 998244353
G = 3

# https://github.com/ddfkit/acsampl/blob/main/ntt.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def ntt(a,inv=False):
    n=len(a);j=0
    for i in range(1,n):
        b=n>>1
        while j&b:j^=b;b>>=1
        j^=b
        if i<j:a[i],a[j]=a[j],a[i]
    l=2
    while l<=n:
        w0=pow(G,(MOD-1)//l,MOD)
        if inv:w0=pow(w0,MOD-2,MOD)
        hl=l>>1
        for i in range(0,n,l):
            w=1
            for k in range(i,i+hl):
                u,v=a[k],a[k+hl]*w%MOD
                a[k],a[k+hl]=(u+v)%MOD,(u-v)%MOD;w=w*w0%MOD
        l<<=1
    if inv:
        inv_n=pow(n,MOD-2,MOD)
        for i in range(n):a[i]=a[i]*inv_n%MOD

# https://github.com/ddfkit/acsampl/blob/main/ntt.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def convolve_ntt(a,b):
    deg=len(a)+len(b)-1;n=1<<(deg-1).bit_length()
    fa=a+[0]*(n-len(a));fb=b+[0]*(n-len(b))
    ntt(fa);ntt(fb)
    for i in range(n):fa[i]=fa[i]*fb[i]%MOD
    ntt(fa,True)
    return fa[:deg]

if __name__ == "__main__":
    A = [1, 2, 3]
    B = [4, 5]
    C = convolve_ntt(A, B)
    assert C == [4, 13, 22, 15]
    print("ntt.py: tests passed!")
